    public void respond(@Val Rate rate, Rates rates, ObjectResponse<RateResponse> response) {
        response.send(RateResponse.from(rates.onSheet(rate.sheetId()).stream()
                .filter(r -> r.grade().equals(rate.grade()) && Objects.equals(r.from(), rate.from()))
                .findFirst().orElse(rate)));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.stereotype.Repository;

/** The rates for each grade of each sheet; a grade has at most one in force per from-date (or none), the
 *  newest of its versions. */
@Repository
public class Rates {

    private final JdbcTemplate jdbc;

    public Rates(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every rate on the sheet, by grade, then by from-date (the one with none first), each with its older versions. */
    public List<Rate> onSheet(String sheetId) {
        Map<String, List<Rate.Version>> earlier = new HashMap<>();
        jdbc.query("SELECT grade, from_date, pct, to_date, forward_after FROM rate_version WHERE sheet_id = ? ORDER BY version DESC",
                (RowCallbackHandler) rs -> earlier.computeIfAbsent(rs.getString("grade") + "/" + rs.getDate("from_date"),
                        k -> new ArrayList<>()).add(new Rate.Version(rs.getBigDecimal("pct"), date(rs.getDate("to_date")),
                                forwardAfter(rs))),
                sheetId);
        return jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date, version, forward_after FROM rate WHERE sheet_id = ? ORDER BY grade, from_key",
                (rs, i) -> new Rate(rs.getString("sheet_id"), rs.getString("grade"), rs.getBigDecimal("pct"),
                        date(rs.getDate("from_date")), date(rs.getDate("to_date")), rs.getInt("version"), forwardAfter(rs),
                        earlier.getOrDefault(rs.getString("grade") + "/" + rs.getDate("from_date"), List.of())),
                sheetId);
    }

    private static LocalDate date(Date date) {
        return date != null ? date.toLocalDate() : null;
    }

    private static Long forwardAfter(ResultSet rs) throws SQLException {
        long after = rs.getLong("forward_after");
        return rs.wasNull() ? null : after;
    }

    /** How many levels of parent sheets a grade's rate is looked for in. */
    public static final int PARENT_LEVELS = 3;

    /** The grade's rate in force on `date`: the sheet's own (see {@link #ownPct}), else that of the
     *  first sheet of its {@link #lineage} with one then; null when none has one. */
    public BigDecimal pct(String sheetId, String grade, LocalDate date) {
        return pct(sheetId, grade, date, null);
    }

    /** The grade's rate that applies on `date` to the claim with sequence `seq` (see {@link #ownPct}): as
     *  {@link #pct(String, String, LocalDate)}, passing over each forward-only rate saved after the claim
     *  was added. Null `seq` (a claim not yet added) passes over none. */
    public BigDecimal pct(String sheetId, String grade, LocalDate date, Long seq) {
        BigDecimal own = ownPct(sheetId, grade, date, seq);
        if (own != null) return own;
        for (String sheet : lineage(sheetId)) {
            BigDecimal pct = ownPct(sheet, grade, date, seq);
            if (pct != null) return pct;
        }
        return null;
    }

    /** The sheets a grade's rate is looked for in after the sheet's own, nearest first: its parent sheets,
     *  up to {@link #PARENT_LEVELS} levels up; then, for a cloned sheet, the sheet it was cloned from
     *  followed by that one's own lineage. Each sheet appears once. */
    public List<String> lineage(String sheetId) {
        return lineage(sheetId, parent(sheetId));
    }

    /** As {@link #lineage(String)}, with the sheet's parent given (null for none). */
    public List<String> lineage(String sheetId, String parent) {
        List<String> lineage = new ArrayList<>();
        Set<String> seen = new HashSet<>(List.of(sheetId));
        String sheet = sheetId;
        String up = parent;
        while (true) {
            for (int level = 1; up != null && level <= PARENT_LEVELS && seen.add(up); level++) {
                lineage.add(up);
                up = parent(up);
            }
            String source = source(sheet);
            if (source == null || !seen.add(source)) return lineage;
            lineage.add(source);
            sheet = source;
            up = parent(source);
        }
    }

    /** The sheet the sheet was cloned from, or null when it was not cloned. */
    public String source(String sheetId) {
        return jdbc.queryForList("SELECT source_id FROM PUBLIC.sheet_source WHERE sheet_id = ?", String.class, sheetId)
                .stream().findFirst().orElse(null);
    }

    /** The sheet's parent sheet id, or null when it names none. */
    public String parent(String sheetId) {
        return jdbc.query("SELECT parent_id FROM sheet_setting WHERE sheet_id = ?",
                (rs, i) -> rs.getString("parent_id"), sheetId)
                .stream().filter(p -> p != null).findFirst().orElse(null);
    }

    /** The rates of the sheet's {@link #lineage}, nearest first, each sheet with every rate set on it. */
    public List<Inherited> inherited(String sheetId) {
        List<Inherited> inherited = new ArrayList<>();
        int level = 1;
        for (String sheet : lineage(sheetId)) inherited.add(new Inherited(level++, sheet, onSheet(sheet)));
        return inherited;
    }

    /** The rates of a sheet of the lineage, `level` places along it (1 for the nearest). */
    public record Inherited(int level, String sheetId, List<Rate> rates) {
    }

    /** The grade's rate in force on `date` set on the sheet itself: the one with the latest from-date
     *  on or before it, or null when there is none or that one's to-date is before `date`. With a claim's
     *  sequence `seq`, the rate that applies to that claim: a forward-only version saved after the claim
     *  was added is passed over for the newest version of its from-date that applies, and a from-date
     *  with none that applies is passed over for the one before. */
    public BigDecimal ownPct(String sheetId, String grade, LocalDate date, Long seq) {
        String applies = seq == null ? "" : " AND (forward_after IS NULL OR forward_after < ?)";
        String versions = seq == null ? "SELECT from_key, version, pct, to_date FROM rate WHERE sheet_id = ? AND grade = ?" + applies
                : "SELECT from_key, version, pct, to_date FROM rate WHERE sheet_id = ? AND grade = ?" + applies
                        + " UNION ALL SELECT from_key, version, pct, to_date FROM rate_version WHERE sheet_id = ? AND grade = ?" + applies;
        List<Object> args = new ArrayList<>(List.of(sheetId, grade));
        if (seq != null) args.addAll(List.of(seq, sheetId, grade, seq));
        args.add(Date.valueOf(date));
        return jdbc.query("SELECT pct, to_date FROM (" + versions + ") v WHERE from_key <= ?"
                + " ORDER BY from_key DESC, version DESC LIMIT 1",
                (rs, i) -> {
                    Date to = rs.getDate("to_date");
                    return to != null && to.toLocalDate().isBefore(date) ? null : rs.getBigDecimal("pct");
                }, args.toArray())
                .stream().filter(p -> p != null).findFirst().orElse(null);
    }

    /** Set the grade's rate from its from-date as its newest version: the one it had for that from-date
     *  is kept as an older version. Saved with a from-date on or after the sheet's `today`, it is
     *  forward-only: it applies only to the claims added from now on (see {@link Rate#forwardAfter}). */
    public void save(Rate rate, LocalDate today) {
        Date from = rate.from() != null ? Date.valueOf(rate.from()) : null;
        Long forwardAfter = rate.from() != null && today != null && !rate.from().isBefore(today)
                ? jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) FROM PUBLIC.claim", Long.class) : null;
        Integer current = jdbc.query("SELECT version FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                (rs, i) -> rs.getInt("version"), rate.sheetId(), rate.grade(), from).stream().findFirst().orElse(null);
        if (current != null) {
            jdbc.update("INSERT INTO rate_version (sheet_id, grade, from_date, version, pct, to_date, forward_after) "
                    + "SELECT sheet_id, grade, from_date, version, pct, to_date, forward_after FROM rate "
                    + "WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                    rate.sheetId(), rate.grade(), from);
            jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                    rate.sheetId(), rate.grade(), from);
        }
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date, version, forward_after) VALUES (?, ?, ?, ?, ?, ?, ?)",
                rate.sheetId(), rate.grade(), rate.pct(), from, rate.to() != null ? Date.valueOf(rate.to()) : null,
                current != null ? current + 1 : 1, forwardAfter);
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.settings.Settings;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 *
 * A change made by a user acting as a steward by delegation (the sheet's today inside the range)
 * ends each of its lines with for=<the steward who delegated> (a SNAPSHOT among them: it is written
 * by the today change the user makes); the lines that only report figures (ROLLUP, TOTALS, ALERT) do not.
 */
@Service
public class Audit {

    /** The events that only report figures: never marked for a delegating steward. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private static final Pattern SHEET_BY = Pattern.compile("^(\\S+) sheet=(\\S+) by=(\\S+)");

    private final Path file;
    private final Settings settings;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, Settings settings) {
        this.file = Path.of(path);
        this.settings = settings;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        Matcher m = SHEET_BY.matcher(entry);
        if (m.find() && !FIGURES.contains(m.group(1))) {
            String delegator = settings.delegator(m.group(2), m.group(3));
            if (delegator != null) {
                entry = entry + " for=" + delegator;
            }
        }
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * The sheet's lines exactly as the file holds them, newest first. With a name given, only the
     * lines carrying name=<the name> or person=<the name>, compared as names are (case and the
     * spaces around it ignored). Reads the file; records nothing.
     */
    public synchronized List<String> linesFor(String sheet, String name) {
        List<String> all;
        try {
            all = Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        String key = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
        List<String> lines = new ArrayList<>();
        for (int i = all.size() - 1; i >= 0; i--) {
            String line = all.get(i);
            Matcher m = SHEET_BY.matcher(line);
            if (!m.find() || !m.group(2).equals(sheet)) {
                continue;
            }
            if (key.isEmpty() || about(line, key)) {
                lines.add(line);
            }
        }
        return lines;
    }

    /**
     * A claim's lines on the sheet exactly as the file holds them, newest first: with a number, the
     * lines carrying number=<it>; without one, the lines carrying no number that name its person,
     * amount and date together (person=, amount= and date= those values). Reads the file; records nothing.
     */
    public synchronized List<String> timelineFor(String sheet, String number, String person, String amount,
            String date) {
        List<String> lines = new ArrayList<>();
        for (String line : linesFor(sheet, null)) {
            String padded = " " + line + " ";
            if (number != null) {
                if (padded.contains(" number=" + number + " ")) lines.add(line);
            } else if (person != null && !padded.contains(" number=")
                    && padded.contains(" person=" + person + " ") && padded.contains(" amount=" + amount + " ")
                    && padded.contains(" date=" + date + " ")) {
                lines.add(line);
            }
        }
        return lines;
    }

    /** Whether the line's name= or person= field holds this (lower-cased, trimmed) name. */
    private static boolean about(String line, String key) {
        String[] tokens = line.split(" ");
        for (int i = 0; i < tokens.length; i++) {
            String value;
            if (tokens[i].startsWith("name=")) {
                value = tokens[i].substring("name=".length());
            } else if (tokens[i].startsWith("person=")) {
                value = tokens[i].substring("person=".length());
            } else {
                continue;
            }
            // A name with spaces in it runs on until the next field (a token carrying '=').
            StringBuilder full = new StringBuilder(value);
            for (int j = i + 1; j < tokens.length && !tokens[j].contains("="); j++) {
                full.append(' ').append(tokens[j]);
            }
            if (full.toString().trim().toLowerCase(Locale.ROOT).equals(key)) {
                return true;
            }
        }
        return false;
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

