import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimsKey } from '../claims/useClaims';
import { holidaysKey, useHolidays, type Holiday } from './useHolidays';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * The sheet's holidays and a date entry to add one. A claim's due-by fixed at creation that falls
 * on a holiday moves to the next day that is not one; a date already on the list is refused.
 */
function HolidaysPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data: holidays = [] } = useHolidays(sheet);
  const [date, setDate] = useState('');
  const [invalid, setInvalid] = useState(false);

  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (d: string) => postJson<Holiday>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`, { date: d, user }),
    onSuccess: async () => {
      setDate('');
      await queryClient.invalidateQueries({ queryKey: holidaysKey(sheet) });
      // A new holiday re-fixes the due-by of the claims due by it or later.
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });

  // An error goes as soon as its form is changed or submitted again.
  const clearError = () => {
    add.reset();
    setInvalid(false);
  };

  return (
    <section data-testid="holidays-panel">
      <h2>Holidays</h2>
      <form
        data-testid="holiday-form"
        onSubmit={(e) => {
          e.preventDefault();
          const d = date.trim();
          if (!DATE.test(d) || holidays.some((h) => h.date === d)) {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            add.reset();
            setInvalid(true);
            return;
          }
          setInvalid(false);
          submitOnce(() => add.mutateAsync(d));
        }}
      >
        <label>
          Date{' '}
          <input
            data-testid="holiday-date"
            placeholder="yyyy-mm-dd"
            value={date}
            onChange={(e) => {
              setDate(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="holiday-add" disabled={add.isPending}>
          Add holiday
        </button>
        {(invalid || add.isError) && (
          <span data-testid="holiday-error" role="alert">
            {' '}
            {invalid ? 'Enter a date (yyyy-mm-dd) not already on the list.' : 'Could not add this holiday.'}
          </span>
        )}
      </form>
      <ul data-testid="holiday-list">
        {holidays.map((h) => (
          <li key={h.date} data-testid={`holiday-row-${h.date}`}>
            {h.date}
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 7, Component: HolidaysPanel });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** A holiday as the server sends it: its date, yyyy-mm-dd. */
export type Holiday = { date: string };

export const holidaysKey = (sheet: string) => ['sheet', sheet, 'holidays'] as const;

/** The sheet's holidays, earliest first, re-read whenever the sheet is loaded. */
export function useHolidays(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(holidaysKey(sheet), asOf),
    queryFn: () => getJson<Holiday[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/holidays`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { defineSlot } from '../Slot';

/**
 * The active sheet's content on the home screen. Rendered only once someone is signed in and a
 * sheet is loaded; everything kept per sheet contributes a panel here, keyed by `sheet`.
 */
export const SheetPanels = defineSlot<{ user: string; sheet: string }>('sheet.panels');

